              {/* Loading Bar */}
              <motion.div 
                 className="w-48 h-[2px] bg-foreground/10 overflow-hidden relative mt-4"
                 initial={{ opacity: 0 }}
                 animate={{ opacity: 1 }}
                 transition={{ delay: 1 }}
              >
                 <motion.div 
                   className="absolute inset-0 bg-accent"
                   initial={{ x: "-100%" }}
                   animate={{ x: "0%" }}
                   transition={{ duration: 1.5, ease: "easeInOut" }}
                 />
              </motion.div>
           </motion.div>

           {/* Footer Text */}
           <motion.div
